/* Scenario baseline and explicit, non-clinical approval workflow. */
const protocolRelease={id:'FN-ADULT-DEMO',version:'0.12',title:'Adult FN clinical review framework',sourceStatus:'IDSA 2010 archived; ASCO/IDSA 2018; FDA cefepime 07/2025 label reference. Local reconciliation pending.',scope:'FN-1 through FN-6 draft templates; limited cefepime reference only'};
state.protocolApprovals??=[];
function protocolFingerprint(){return JSON.stringify({release:protocolRelease,templates,sources:orderSources})}
function approvalStatus(){const fp=protocolFingerprint(),rows=state.protocolApprovals.filter(r=>r.fingerprint===fp),roles=['Oncology / infectious diseases','Clinical pharmacy','CDS governance'];return {roles,rows,complete:roles.every(role=>{const r=rows.find(r=>r.role===role);return r?.decision==='Demo approval'&&new Date(r.nextReview)>new Date()})};}
function protocolBadge(){return `<div class="notice"><b>${esc(protocolRelease.id)} · v${protocolRelease.version}</b><br>Clinical status: <b>Draft — pending clinical and pharmacy approval</b><br>Simulation: ${approvalStatus().complete?'Demo approval complete — simulation only':'Demo review pending'} · <button class="btn" onclick="go('Scope & evidence')">Sources & approval</button></div>`}
function baselinePanel(){const s=state.quarterScenario;return `<section class="panel" style="margin-bottom:20px"><div class="sectiontitle"><div><h2>Baseline & comparison</h2><p>Simulated baseline — for capstone demonstration</p></div><button class="btn" onclick="exportBaseline()">Export baseline</button></div><p><span class="pill amber">All values invented</span> ${esc(s.baseline)} → ${esc(s.followup)} · ${s.cohort} fictional FN episodes per quarter. Separate from patient registry and current episode audit.</p><details><summary>View baseline values and comparison</summary><div class="scroll"><table><thead><tr><th>Indicator</th><th>Baseline</th><th>Comparison</th><th>Change</th></tr></thead><tbody>${s.clinical.map(m=>`<tr><td>${esc(m.label)}</td><td>${m.before}/${m.denom} · ${(100*m.before/m.denom).toFixed(1)}%</td><td>${m.after}/${m.denom} · ${(100*m.after/m.denom).toFixed(1)}%</td><td>${(100*(m.after-m.before)/m.denom).toFixed(1)} pp</td></tr>`).join('')}</tbody></table></div><p>Source: invented CEO-SIM scenario. Same counts as the clinical CEO dashboard; no causal effectiveness claim. Outcomes can overlap and must not be summed.</p></details><details><summary>Actual baseline — not supplied</summary><p>No actual hospital baseline is loaded. Collect approved encounter data with source, observation period, eligibility, exclusions, actual administration timestamps and independent appropriateness review. Current synthetic episode audit is not an actual hospital baseline.</p></details></section>`}
function exportBaseline(){download('FN_SIMULATED_baseline.json',{synthetic:true,origin:'Invented capstone scenario',actualBaseline:null,baseline:state.quarterScenario.baseline,comparison:state.quarterScenario.followup,cohort:state.quarterScenario.cohort,metrics:state.quarterScenario.clinical,causalEvidence:false});save('Exported simulated baseline; actual baseline not supplied')}
function approvalPanel(){const a=approvalStatus();return `<section class="panel" style="margin-bottom:20px"><div class="sectiontitle"><div><h2>Protocol & medication approval</h2><p>${esc(protocolRelease.id)} · version ${protocolRelease.version}</p></div><button class="btn" onclick="exportProtocolRegistry()">Export registry</button></div><p><span class="pill amber">Draft — pending clinical and pharmacy approval</span></p><p>Demo workflow: <b>${a.complete?'Demo approval complete — simulation only':'Pending demo reviews'}</b>. Local reviewer labels are not authenticated signatures and cannot approve clinical use.</p><details><summary>Sources, medication scope and review workflow</summary><p>${esc(protocolRelease.sourceStatus)}</p><div class="scroll"><table><thead><tr><th>Reference</th><th>Scope</th><th>Approval</th></tr></thead><tbody>${Object.entries(orderSources).map(([k,s])=>`<tr><td><a href="${s.url}" target="_blank" rel="noopener">${esc(s.label)}</a></td><td>${k==='cefepime'?'Limited label dose / renal reference; no complete formulary':'Source-linked clinical review templates'}</td><td>Local approval pending</td></tr>`).join('')}</tbody></table></div><p>Institutional owner, formulary, antibiogram and real approval dates remain unassigned. Drug references do not authorize prescribing. No demo action changes the clinical status above or enables executable orders.</p><div class="grid2">${a.roles.map(role=>{const r=a.rows.find(r=>r.role===role);return `<div class="card"><h3>${esc(role)}</h3><p>${r?esc(r.decision)+' · '+esc(r.reviewer)+' · '+fmt(r.time):'No demo decision recorded'}</p>${r?`<p>Review due: ${esc(r.nextReview)} ${new Date(r.nextReview)<=new Date()?'· overdue':''}</p>`:''}<button class="btn" onclick="openProtocolDecision('${role}')">Record demo decision</button></div>`}).join('')}</div><h3>Review history</h3>${state.protocolApprovals.length?`<div class="scroll"><table><thead><tr><th>Role / reviewer</th><th>Decision</th><th>Time / next review</th><th>Rationale</th></tr></thead><tbody>${state.protocolApprovals.map(r=>`<tr><td>${esc(r.role)}<br>${esc(r.reviewer)}</td><td>${esc(r.decision)}${r.fingerprint!==protocolFingerprint()?' · prior release':''}</td><td>${fmt(r.time)}<br>${esc(r.nextReview)}</td><td>${esc(r.note)}</td></tr>`).join('')}</tbody></table></div>`:'<p>No demo review history yet.</p>'}</details></section>`}
function openProtocolDecision(role){if(!approvalStatus().roles.includes(role))return;openDialog('Protocol review — simulation only',`<p>${esc(role)} · ${esc(protocolRelease.id)} v${protocolRelease.version}. This is a capstone rehearsal, not institutional approval.</p><form onsubmit="event.preventDefault();saveProtocolDecision(this)"><input type="hidden" name="role" value="${esc(role)}"><label class="field">Fictional reviewer label<input name="reviewer" required maxlength="120"></label><label class="field">Demo decision<select name="decision"><option>Changes requested</option><option>Demo approval</option></select></label><label class="field">Next review date<input name="nextReview" type="date" min="${new Date(Date.now()+86400000).toISOString().slice(0,10)}" required></label><label class="field">Rationale and outstanding limitations<textarea name="note" required maxlength="800"></textarea></label><label><input name="confirm" type="checkbox" required> I understand this records a simulation only</label><p id="protocolError" role="alert"></p><div class="actions"><button class="btn primary" type="submit">Save demo decision</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></div></form>`)}
function saveProtocolDecision(form){const f=new FormData(form),r=Object.fromEntries(f);if(!approvalStatus().roles.includes(r.role)||!['Demo approval','Changes requested'].includes(r.decision)||!r.reviewer?.trim()||!r.note?.trim()||!r.confirm||!/^\d{4}-\d{2}-\d{2}$/.test(r.nextReview)||new Date(r.nextReview)<=new Date()){document.querySelector('#protocolError').textContent='Complete reviewer, rationale, a future review date and simulation acknowledgement.';return}state.protocolApprovals.unshift({role:r.role,reviewer:r.reviewer.trim(),decision:r.decision,note:r.note.trim(),nextReview:r.nextReview,time:new Date().toISOString(),fingerprint:protocolFingerprint(),version:protocolRelease.version,simulationOnly:true});closeDialog();save('Protocol '+r.decision+' (simulation only) by '+r.role)}
function exportProtocolRegistry(){download('FN_DEMO_protocol_registry.json',{release:protocolRelease,clinicalStatus:'DRAFT_PENDING_INSTITUTIONAL_APPROVAL',simulationOnly:true,demoComplete:approvalStatus().complete,sources:orderSources,history:state.protocolApprovals});save('Exported draft protocol registry; simulation only')}
const orderBeforeApproval=orderView;orderView=function(){return protocolBadge()+orderBeforeApproval()};
const orderExportBeforeApproval=exportOrder;exportOrder=function(){const o=state.orderDrafts[id(selected)];if(!o)return;download(id(selected)+'-DRAFT-orders.json',{status:'NOT_EXECUTABLE_NOT_SIGNED',patient:id(selected),...o,context:undefined,contextChanged:o.context!==orderContext(id(selected)),sources:orderSources,protocol:{...protocolRelease,clinicalStatus:'DRAFT_PENDING_INSTITUTIONAL_APPROVAL',demoComplete:approvalStatus().complete}});save('Exported order draft with protocol approval status',id(selected))};
const renderBeforeBaselineApproval=render;render=function(){renderBeforeBaselineApproval();if(view==='Clinical quality')$('#app').insertAdjacentHTML('afterbegin',baselinePanel());if(view==='Scope & evidence'||view==='Alert governance')$('#app').insertAdjacentHTML('afterbegin',approvalPanel())};
